CREATE OR REPLACE FUNCTION public.get_reschedule_slots(p_appointment_id uuid,p_date date,p_professional_id uuid DEFAULT NULL) RETURNS TABLE(slot_start timestamptz,slot_end timestamptz,total_duration_minutes integer,total_amount bigint) LANGUAGE plpgsql STABLE SECURITY INVOKER SET search_path='' AS $$ DECLARE a public.appointments; slug text; ids uuid[]; BEGIN SELECT * INTO a FROM public.appointments WHERE id=p_appointment_id AND business_id=public.current_business_id(); IF NOT FOUND OR NOT public.is_admin() THEN RAISE EXCEPTION 'Reserva no disponible.'; END IF; IF a.status NOT IN ('pending_payment','pending_verification','confirmed') THEN RAISE EXCEPTION 'Esta reserva no se puede mover.'; END IF; SELECT b.slug INTO slug FROM public.businesses b WHERE b.id=a.business_id; SELECT array_agg(s.service_id) INTO ids FROM public.appointment_services s WHERE s.appointment_id=a.id AND s.business_id=a.business_id; RETURN QUERY SELECT * FROM public.booking_slots_internal(p_date,ids,slug,p_professional_id,a.id,a.duration_minutes); END; $$;
CREATE OR REPLACE FUNCTION public.reschedule_appointment(p_appointment_id uuid,p_start_at timestamptz,p_professional_id uuid DEFAULT NULL) RETURNS boolean LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $$ DECLARE a public.appointments; tz text; BEGIN IF NOT public.is_admin() THEN RAISE EXCEPTION 'Acceso reservado al propietario.'; END IF; PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(public.current_business_id()::text,987)); SELECT * INTO a FROM public.appointments WHERE id=p_appointment_id AND business_id=public.current_business_id() FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Reserva no disponible.'; END IF; SELECT s.timezone INTO tz FROM public.business_settings s WHERE s.business_id=a.business_id; IF NOT EXISTS(SELECT 1 FROM public.get_reschedule_slots(a.id,(p_start_at AT TIME ZONE tz)::date,p_professional_id) s WHERE s.slot_start=p_start_at) THEN RAISE EXCEPTION 'El horario ya no está disponible.'; END IF; UPDATE public.appointments SET start_at=p_start_at,end_at=p_start_at+make_interval(mins=>a.duration_minutes),professional_id=p_professional_id WHERE id=a.id AND business_id=a.business_id; RETURN true; END; $$;